import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"发布流程","description":"","frontmatter":{},"headers":[],"relativePath":"zh/contribute/release.md","filePath":"zh/contribute/release.md","lastUpdated":1793024217000}'),c={name:"zh/contribute/release.md"};function r(i,e,s,l,n,h){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="发布流程" tabindex="-1">发布流程 <a class="header-anchor" href="#发布流程" aria-label="Permalink to &quot;发布流程&quot;">​</a></h1><p>发布是自动的。每次推送到默认分支且改动了程序本身，CI 通过后就会发布新版本；不需要手动修改版本号或推送标签。</p><h2 id="合并之前" tabindex="-1">合并之前 <a class="header-anchor" href="#合并之前" aria-label="Permalink to &quot;合并之前&quot;">​</a></h2><ol><li>在两种语言<a href="/meetcue/zh/reference/changelog">更新日志</a>的 <strong>未发布</strong> 部分写上本次改动。发布时这些条目会移到新版本标题下，并用作发布说明。</li><li>对照各供应商的定价页面核对 <code>crates/core/data/pricing.json</code> 中的价格，有变化时更新 <code>verified</code> 日期和 <code>updated</code>。程序从文档站下载这个文件，所以修正价格只需推送到默认分支，无需发布新版本。</li><li>涉及音频、语音识别或窗口的改动，请在 Windows 电脑上用该分支的构建运行<a href="/meetcue/zh/test-checklist">实机测试清单</a>（CI 会为每次推送上传 <code>MeetCue-windows-x64</code>）。</li></ol><h2 id="版本号如何确定" tabindex="-1">版本号如何确定 <a class="header-anchor" href="#版本号如何确定" aria-label="Permalink to &quot;版本号如何确定&quot;">​</a></h2><p>新版本号是最新的 <code>v*</code> 标签把修订号加一。在拉取请求标题中，或在直接推送到默认分支的提交标题中加入标记，可以改变这一点。只出现在说明正文中的标记会被忽略，所以介绍这些标记不会误触发。</p><table tabindex="0"><thead><tr><th>标记</th><th>效果</th></tr></thead><tbody><tr><td><code>[release minor]</code></td><td>0.1.5 → 0.2.0</td></tr><tr><td><code>[release major]</code></td><td>0.1.5 → 1.0.0</td></tr><tr><td><code>[skip release]</code></td><td>写在最新的提交中：本次推送不发布</td></tr></tbody></table><p>只改动文档、工作流或 Scoop manifest 的推送不会发布。需要手动发布时，在 Actions 页面运行 <strong>Release</strong> 工作流并选择要增加的部分。</p><h2 id="发布工作流做了什么" tabindex="-1">发布工作流做了什么 <a class="header-anchor" href="#发布工作流做了什么" aria-label="Permalink to &quot;发布工作流做了什么&quot;">​</a></h2><p>默认分支上的 CI 完成后会运行 <code>.github/workflows/release.yml</code>：</p><ol><li>确定版本号。只发布最新的提交：如果 CI 运行期间分支又有新提交，由新提交的运行一并发布。</li><li>在 Windows 上用这个版本号构建 <code>MeetCue.exe</code>，检查 <code>MeetCue.exe --version</code>，并把 <code>MeetCue.exe</code>、<code>LICENSE</code> 和 README 文件打包为 <code>meetcue-win-x64.zip</code>。</li><li>运行 <code>scripts/set-version.mjs</code>：把版本号写入 <code>Cargo.toml</code>、<code>Cargo.lock</code>、各 <code>package.json</code> 和 <code>package-lock.json</code>，把更新日志中 <strong>未发布</strong> 的条目移到新版本下，并让 <code>bucket/meetcue.json</code> 指向新的 zip 及其 SHA-256 哈希。</li><li>以仓库变量 <code>GIT_NAME</code> 和 <code>GIT_EMAIL</code> 的身份把这些改动提交到默认分支（&quot;Release x.y.z&quot;），并打上 <code>vx.y.z</code> 标签。提交和标签一起推送；如果分支在此期间有了新提交，则什么都不发布，由下一次运行发布。</li><li>创建 GitHub Release，上传 zip，并以更新日志中的这一节作为发布说明，然后重新发布文档站。</li><li>在 Windows 构建机上安装 Scoop，用标签中的 manifest 安装 MeetCue，确认输出新版本号。</li></ol><p><code>npm run check:versions</code> 会检查所有 manifest、两个锁文件和 Scoop manifest 的版本号一致，因此提交中的版本号始终等于最新发布的版本。哈希只由工作流在上传 zip 的同一次运行中计算并提交。不要手动替换 Release 中的文件；需要修改时请发布新版本。</p><p>如果提交和标签已推送后某个步骤失败，使用 <strong>Re-run failed jobs</strong>，它会为同一标签完成发布。</p><h2 id="发布之后" tabindex="-1">发布之后 <a class="header-anchor" href="#发布之后" aria-label="Permalink to &quot;发布之后&quot;">​</a></h2><ol><li>在 Windows 电脑上确认 <code>scoop update meetcue</code> 能升级到新版本。</li><li>确认文档站点显示了新的更新日志。</li></ol><h2 id="仓库设置" tabindex="-1">仓库设置 <a class="header-anchor" href="#仓库设置" aria-label="Permalink to &quot;仓库设置&quot;">​</a></h2><p>以下设置只需配置一次：</p><ul><li><strong>Settings › Pages</strong>：来源设为 <code>gh-pages</code> 分支。默认分支上 <code>docs/</code> 或 <code>errors.json</code> 有变化时，文档工作流会发布到这里。</li><li><strong>Settings › Secrets and variables › Actions › Variables</strong>：设置 <code>GIT_NAME</code> 和 <code>GIT_EMAIL</code>，供工作流提交时使用。</li><li><strong>Settings › Actions › General › Workflow permissions</strong>：工作流用 <code>GITHUB_TOKEN</code> 推送到默认分支，如果默认分支有保护规则，需要允许 GitHub Actions 推送。</li><li>仓库必须是公开的，否则 Scoop 无法下载 Release 中的文件。</li></ul>',18)])])}const m=o(c,[["render",r]]);export{u as __pageData,m as default};
